using TdLib.TdApi;
using TdLib.TdApi.Objects;
namespace TdLib.Api.OpenTelemetry;
/// <summary>
/// Autogenerated TDLib APIs
/// </summary>

public partial class ClientOpenTelemetryDecorator
{
    /// <summary>
    /// Edits the text of an inline text or game message sent via a bot; for bots only
    /// </summary>
    public Task<TdLib.TdApi.Objects.Ok> EditInlineMessageTextAsync(string inlineMessageId = default, ReplyMarkup replyMarkup = default, InputMessageContent inputMessageContent = default)
    {

           using var activity =  StartCallActivity("EditInlineMessageTextAsync", typeof(EditInlineMessageText).FullName ?? "EditInlineMessageTextAsync");

           try
           {
             return client.EditInlineMessageTextAsync(inlineMessageId, replyMarkup, inputMessageContent);
           }
           catch (Exception ex)
           {
               MarkAsError(activity, ex);
               throw;
           }
    }
}
